from marshmallow import Schema, fields

def test_pluck_empty_data_key():
    class ChildSchema(Schema):
        value = fields.Integer(data_key='')
    class ParentSchema(Schema):
        child = fields.Pluck(ChildSchema, 'value')
    schema = ParentSchema()
    serialized = {'child': 2}
    deserialized = {'child': {'value': 2}}
    assert schema.load(serialized) == deserialized

import more_itertools as mi

def test_falsey_validator():
    class AllowedKeys(set):
        def __call__(self, key):
            return key in self
    allowed = AllowedKeys()
    D = mi.bucket(iter([10, 20, 11, 21]), key=lambda x: x, validator=allowed)
    assert list(D[10]) == []

